-- PostgreSQL: student 2045230070, lecturer GV003 (Tran Khai Thien), AAA / 2013J.
-- Synthetic chart data, not actual academic observations.
-- Prediction values below are generated by the application's model.
BEGIN;
DO $seed$
DECLARE
    v_student uuid;
    v_presentation uuid;
    v_enrollment uuid;
    v_credits integer;
    v_registration integer;
BEGIN
    SELECT id INTO STRICT v_student FROM student_profiles
    WHERE student_code = '2045230070' FOR UPDATE;

    SELECT cp.id INTO STRICT v_presentation
    FROM course_presentations cp
    JOIN courses c ON c.id = cp.course_id
    JOIN course_lecturers cl ON cl.presentation_id = cp.id
    JOIN lecturer_profiles lp ON lp.id = cl.lecturer_id
    WHERE lp.lecturer_code = 'GV003'
      AND c.code_module = 'AAA' AND cp.code_presentation = '2013J'
      AND cp.module_presentation_length = 268
      AND cp.start_date IS NOT NULL;

    IF EXISTS (
        SELECT 1 FROM student_feature_snapshots s
        JOIN student_enrollments e ON e.id = s.enrollment_id
        WHERE e.student_id = v_student AND e.presentation_id = v_presentation
          AND s.raw_features_json->>'demo_fixture' = 'charts-2045230070-2026-10-23'
    ) THEN
        RAISE NOTICE 'Fixture already exists; no changes applied';
        RETURN;
    END IF;

    INSERT INTO student_enrollments
        (id, student_id, presentation_id, date_registration, studied_credits, num_of_prev_attempts)
    VALUES (gen_random_uuid(), v_student, v_presentation, -10, 60, 0)
    ON CONFLICT (student_id, presentation_id) DO NOTHING;

    SELECT id, studied_credits, date_registration
    INTO STRICT v_enrollment, v_credits, v_registration
    FROM student_enrollments
    WHERE student_id = v_student AND presentation_id = v_presentation;
    IF v_credits <> 60 OR v_registration <> -10 THEN
        RAISE EXCEPTION 'Enrollment differs from inference inputs; regenerate prediction';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM ml_models WHERE id = 'eaba0cc3-2115-4c64-8ac9-d3a222a75da4'
        AND version = 'v1.0.0'
        AND metadata_json->'validated_runtime'->>'model_sha256' = '90c3f6e7bfdac2d9e62bcb836572f1a57c69fee3e4ef3dec22bd60b9850792db'
        AND threshold = 0.5 AND cutoff_fraction = 0.75
    ) THEN
        RAISE EXCEPTION 'Model provenance differs; regenerate prediction';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM student_profiles WHERE id = v_student
        AND gender = 'M' AND highest_education = 'HE Qualification' AND age_band = '0-35')
    THEN
        RAISE EXCEPTION 'Student profile differs from inference inputs; regenerate prediction';
    END IF;

    INSERT INTO student_feature_snapshots (
        id, enrollment_id, cutoff_stage,
        total_clicks_to_t, clicks_resource_to_t, clicks_url_to_t,
        active_days_to_t, active_day_ratio, days_since_last_activity,
        clicks_recent_7, clicks_recent_30,
        assessments_submitted_to_t, late_submissions_to_t, submission_rate,
        raw_features_json, created_at
    ) VALUES (
        'f096e534-14bc-4edc-bc36-582ebac0e77d', v_enrollment, 'CUTOFF_75',
        1800, 700, 260, 95, 95.0 / 201, 1,
        14, 106, 5, 2, 5.0 / 8,
        jsonb_build_object(
            'data_source', 'synthetic_demo',
            'demo_fixture', 'charts-2045230070-2026-10-23',
            'note', 'Synthetic chart data requested by project owner; not real LMS observations.',
            'support_evidence', jsonb_build_object(
                'source', 'Synthetic fixture for lecturer charts',
                'snapshot_day', 201,
                'confirmed_at', CURRENT_TIMESTAMP,
                'confirmation_kind', 'synthetic_fixture_consistency_only',
                'activity_complete', true,
                'assessments_complete', true,
                'assessment_records', '[
                    {"id":910001,"type":"TMA","due_day":20,"submitted_day":18,"score":88},
                    {"id":910002,"type":"CMA","due_day":40,"submitted_day":43,"score":62},
                    {"id":910003,"type":"TMA","due_day":60,"submitted_day":60,"score":79},
                    {"id":910004,"type":"TMA","due_day":90,"submitted_day":96,"score":51},
                    {"id":910005,"type":"CMA","due_day":120,"submitted_day":118,"score":74},
                    {"id":910006,"type":"TMA","due_day":150,"submitted_day":null,"score":null},
                    {"id":910007,"type":"TMA","due_day":175,"submitted_day":null,"score":null},
                    {"id":910008,"type":"TMA","due_day":195,"submitted_day":null,"score":null}
                ]'::jsonb
            )
        ), CURRENT_TIMESTAMP
    );

    -- Actual model inference with its exact inputs and artifact provenance.
    INSERT INTO prediction_runs (
        id, snapshot_id, model_id, prediction_label, risk_probability,
        inference_context, execution_time_ms, triggered_by_user_id, created_at
    ) VALUES (
        '2d8e7ee9-ebce-48f4-b5e6-929851b08c01', 'f096e534-14bc-4edc-bc36-582ebac0e77d', 'eaba0cc3-2115-4c64-8ac9-d3a222a75da4',
        0, 0.2683858317625138, '{"features": {"total_clicks_to_t": 1800, "clicks_resource_to_t": 700, "clicks_url_to_t": 260, "active_days_to_t": 95, "assessments_submitted_to_t": 5, "late_submissions_to_t": 2, "active_day_ratio": 0.472636815920398, "submission_rate": 0.625, "days_since_last_activity": 1, "clicks_recent_7": 14, "clicks_recent_30": 106, "code_module": "AAA", "gender": "M", "highest_education": "HE Qualification", "age_band": "0-35", "studied_credits": 60.0, "date_registration": -10}, "model_version": "v1.0.0", "threshold": 0.5, "model_sha256": "90c3f6e7bfdac2d9e62bcb836572f1a57c69fee3e4ef3dec22bd60b9850792db", "model_id": "eaba0cc3-2115-4c64-8ac9-d3a222a75da4", "cutoff_fraction": 0.75, "positive_label": 1}'::jsonb, 9, NULL, CURRENT_TIMESTAMP
    );

    INSERT INTO audit_logs (id, user_id, action, target_type, target_id, detail, created_at)
    VALUES (gen_random_uuid(), NULL, 'ADD_SYNTHETIC_CHART_DEMO', 'StudentFeatureSnapshot',
        'f096e534-14bc-4edc-bc36-582ebac0e77d',
        jsonb_build_object('student_code', '2045230070', 'lecturer_code', 'GV003',
            'data_source', 'synthetic_demo', 'requested_by', 'project owner via Codex chat',
            'enrollment_id', v_enrollment, 'prediction_run_id', '2d8e7ee9-ebce-48f4-b5e6-929851b08c01')::text,
        CURRENT_TIMESTAMP);
END;
$seed$;
COMMIT;

-- Inspect the saved data.
SELECT sp.student_code, u.full_name, c.code_module, cp.code_presentation,
       s.id AS snapshot_id, s.total_clicks_to_t, s.submission_rate,
       s.raw_features_json->>'data_source' AS data_source
FROM student_profiles sp
JOIN users u ON u.id = sp.user_id
JOIN student_enrollments e ON e.student_id = sp.id
JOIN course_presentations cp ON cp.id = e.presentation_id
JOIN courses c ON c.id = cp.course_id
JOIN student_feature_snapshots s ON s.enrollment_id = e.id
WHERE sp.student_code = '2045230070'
  AND s.raw_features_json->>'demo_fixture' = 'charts-2045230070-2026-10-23';
